mapper.select:
SELECT T1.CALENDAR_ID calendarId , T1.CDATE cdate , T1.IS_HOLIDAY isHoliday , T1.UPDATE_TIME updateTime, T1.UPDATE_USER updateUser, T2.CALENDAR_NAME calendarName, T1.STATUS status, T1.ERR_MSG errMsg from MST_HOLIDAY T1 left join MST_CALENDAR_INFO T2 on T1.CALENDAR_ID = T2.CALENDAR_ID
#{item}
and T1.IS_HOLIDAY = #{ishDay}
and T1.CDATE >= to_date(#{startDate},'yyyy-MM-dd')
and T1.CDATE <= to_date(#{endDate},'yyyy-MM-dd')
and T1.STATUS = #{status}
ORDER BY calendarId ASC,cdate DESC

select calendar_Id calendarId, calendar_Name calendarName from MST_CALENDAR_INFO
IS_TRADE_CALENDAR = #{no}
AND calendar_Id = #{calendarType}
ORDER BY calendarId ASC

mapper.insert:
MERGE INTO MST_HOLIDAY T USING (
#{item.calendarId,jdbcType=VARCHAR} calendarId, #{item.cdate,jdbcType=DATE} cdate, #{item.dataSource,jdbcType=VARCHAR} dataSource, #{item.status,jdbcType=VARCHAR} status, #{item.isHoliday,jdbcType=INTEGER} isHoliday, #{item.createUser,jdbcType=VARCHAR} createUser, #{item.createDept,jdbcType=VARCHAR} createDept, #{item.createTime,jdbcType=TIMESTAMP} createTime, #{item.updateUser,jdbcType=VARCHAR} updateUser, #{item.updateTime,jdbcType=TIMESTAMP} updateTime, #{item.errMsg,jdbcType=VARCHAR} errMsg
) datas ON (T.CALENDAR_ID = datas.calendarId and T.CDATE = datas.cdate) WHEN MATCHED THEN UPDATE SET T.IS_HOLIDAY = datas.isHoliday,T.ERR_MSG = datas.errMsg, T.UPDATE_USER = datas.updateUser,T.STATUS = datas.status,T.UPDATE_TIME = SYSDATE WHEN NOT MATCHED THEN INSERT ( CALENDAR_ID, CDATE, DATA_SOURCE, STATUS, IS_HOLIDAY, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, ERR_MSG) VALUES ( datas.calendarId, datas.cdate, datas.dataSource, datas.status, datas.isHoliday, datas.createUser, datas.createDept, datas.createTime, datas.updateUser, datas.updateTime, datas.errMsg )

