when cdate=#{item.cdate,jdbcType=DATE} and calendar_id = #{item.calendarId,jdbcType=VARCHAR} then #{item.isHoliday,jdbcType=VARCHAR}
when cdate=#{item.cdate,jdbcType=DATE} and calendar_id = #{item.calendarId,jdbcType=VARCHAR} then #{item.errMsg,jdbcType=VARCHAR}
when cdate=#{item.cdate,jdbcType=DATE} and calendar_id = #{item.calendarId,jdbcType=VARCHAR} then #{item.status,jdbcType=VARCHAR}
when cdate=#{item.cdate,jdbcType=DATE} and calendar_id = #{item.calendarId,jdbcType=VARCHAR} then #{item.createUser,jdbcType=VARCHAR}
when cdate=#{item.cdate,jdbcType=DATE} and calendar_id = #{item.calendarId,jdbcType=VARCHAR} then SYSDATE
where
cdate=#{item.cdate,jdbcType=DATE} and calendar_id = #{item.calendarId,jdbcType=VARCHAR}
